class ExerciseLibraryItem {
  final String id;
  final String name;
  final String englishName;
  final String muscle;
  final IconData icon;
  final String technique;

  const ExerciseLibraryItem({
    required this.id,
    required this.name,
    required this.englishName,
    required this.muscle,
    required this.icon,
    required this.technique,
  });
}

final List<ExerciseLibraryItem> exerciseLibrary = exerciseCatalogData.map((
  item,
) {
  return ExerciseLibraryItem(
    id: item['id']!,
    name: item['name']!,
    englishName: item['englishName']!,
    muscle: item['muscle']!,
    icon: item['equipment'] == 'Cable' ? Icons.cable : Icons.fitness_center,
    technique: item['technique']!,
  );
}).toList();

ExerciseLibraryItem? findExercise(String id) {
  for (final exercise in exerciseLibrary) {
    if (exercise.id == id) {
      return exercise;
    }
  }

  return null;
}

String formatDuration(int seconds) {
  final hours = seconds ~/ 3600;
  final minutes = (seconds % 3600) ~/ 60;
  final remaining = seconds % 60;

  if (hours > 0) {
    return '${hours.toString().padLeft(2, '0')}:'
        '${minutes.toString().padLeft(2, '0')}:'
        '${remaining.toString().padLeft(2, '0')}';
  }

  return '${minutes.toString().padLeft(2, '0')}:'
      '${remaining.toString().padLeft(2, '0')}';
}

