String exerciseImagePath(String exerciseId) {
  const images = {'bench_press': 'assets/exercises/bench_press.png'};

  return images[exerciseId] ?? '';
}

class ExerciseImage extends StatelessWidget {
  final String exerciseId;
  final double size;
  final IconData fallbackIcon;

  const ExerciseImage({
    super.key,
    required this.exerciseId,
    this.size = 60,
    this.fallbackIcon = Icons.fitness_center,
  });

  @override
  Widget build(BuildContext context) {
    final imagePath = exerciseImagePath(exerciseId);

    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        color: pharmacyGreen.withValues(alpha: 0.10),
        borderRadius: BorderRadius.circular(size * 0.28),
      ),
      clipBehavior: Clip.antiAlias,
      child: imagePath.isEmpty
          ? Icon(fallbackIcon, color: pharmacyGreen, size: size * 0.48)
          : Image.asset(
              imagePath,
              fit: BoxFit.cover,
              errorBuilder:
                  (
                    BuildContext imageContext,
                    Object error,
                    StackTrace? stackTrace,
                  ) {
                    return Icon(
                      fallbackIcon,
                      color: pharmacyGreen,
                      size: size * 0.48,
                    );
                  },
            ),
    );
  }
}

