  Future<void> _openPlan(Map<String, dynamic> plan) async {
    await Navigator.push(
      context,
      MaterialPageRoute(builder: (_) => WorkoutPlanPage(plan: plan)),
    );

    if (!mounted) return;

    await _loadPlans();
  }

