class ExerciseConfigDialog extends StatefulWidget {
  final ExerciseLibraryItem exercise;
  final int initialSets;
  final int initialReps;

  const ExerciseConfigDialog({
    super.key,
    required this.exercise,
    this.initialSets = 3,
    this.initialReps = 10,
  });

  @override
  State<ExerciseConfigDialog> createState() => _ExerciseConfigDialogState();
}

class _ExerciseConfigDialogState extends State<ExerciseConfigDialog> {
  String t(String key) => AppTranslations.get(key);
  late int sets;
  late int reps;

  @override
  void initState() {
    super.initState();

    sets = widget.initialSets;
    reps = widget.initialReps;
  }

  Widget _counter({
    required String title,
    required int value,
    required VoidCallback decrease,
    required VoidCallback increase,
  }) {
    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.04),
        borderRadius: BorderRadius.circular(16),
      ),
      child: Row(
        children: [
          Expanded(
            child: Text(
              title,
              style: const TextStyle(
                color: Colors.white,
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
          IconButton(
            onPressed: decrease,
            icon: const Icon(
              Icons.remove_circle_outline,
              color: Colors.white54,
            ),
          ),
          SizedBox(
            width: 35,
            child: Text(
              '$value',
              textAlign: TextAlign.center,
              style: const TextStyle(
                color: pharmacyGreen,
                fontSize: 18,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          IconButton(
            onPressed: increase,
            icon: const Icon(Icons.add_circle_outline, color: pharmacyGreen),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Directionality(
      textDirection: TextDirection.rtl,
      child: AlertDialog(
        backgroundColor: cardColor,
        title: Text(
          widget.exercise.name,
          style: const TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.w900,
          ),
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              widget.exercise.englishName,
              style: const TextStyle(color: mutedColor, fontSize: 12),
            ),
            const SizedBox(height: 18),
            _counter(
              title: t('round_count'),
              value: sets,
              decrease: () {
                if (sets > 1) {
                  setState(() => sets--);
                }
              },
              increase: () {
                if (sets < 20) {
                  setState(() => sets++);
                }
              },
            ),
            const SizedBox(height: 10),
            _counter(
              title: t('target_reps'),
              value: reps,
              decrease: () {
                if (reps > 1) {
                  setState(() => reps--);
                }
              },
              increase: () {
                if (reps < 100) {
                  setState(() => reps++);
                }
              },
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text(t('cancel')),
          ),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: pharmacyGreen),
            onPressed: () {
              Navigator.pop(context, {'sets': sets, 'reps': reps});
            },
            child: Text(t('save')),
          ),
        ],
      ),
    );
  }
}

