class AnimatedExerciseIcon extends StatefulWidget {
  final IconData icon;
  final double size;

  const AnimatedExerciseIcon({super.key, required this.icon, this.size = 60});

  @override
  State<AnimatedExerciseIcon> createState() => _AnimatedExerciseIconState();
}

class _AnimatedExerciseIconState extends State<AnimatedExerciseIcon>
    with SingleTickerProviderStateMixin {
  late final AnimationController controller;

  @override
  void initState() {
    super.initState();

    controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1500),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: controller,
      builder: (_, child) {
        final scale = 0.94 + (controller.value * 0.06);

        return Transform.scale(
          scale: scale,
          child: Container(
            width: widget.size,
            height: widget.size,
            decoration: BoxDecoration(
              color: pharmacyGreen.withValues(alpha: 0.10),
              borderRadius: BorderRadius.circular(widget.size * 0.28),
            ),
            child: Icon(
              widget.icon,
              color: pharmacyGreen,
              size: widget.size * 0.48,
            ),
          ),
        );
      },
    );
  }
}

