class WorkoutSessionPage extends StatefulWidget {
  final int planId;
  final String planName;
  final List<Map<String, dynamic>> exercises;

  const WorkoutSessionPage({
    super.key,
    required this.planId,
    required this.planName,
    required this.exercises,
  });

  @override
  State<WorkoutSessionPage> createState() => _WorkoutSessionPageState();
}

class _WorkoutSessionPageState extends State<WorkoutSessionPage> {
  String t(String key) => AppTranslations.get(key);
  late List<Map<String, dynamic>> sessionExercises;

  Timer? elapsedTimer;
  Timer? restTimer;

  DateTime? startedAt;

  int elapsedSeconds = 0;
  int restSeconds = 0;

  bool saving = false;
  bool finished = false;

  final Map<String, Map<String, dynamic>?> previousPerformance = {};

  bool loadingPrevious = true;

  @override
  void initState() {
    super.initState();

    startedAt = DateTime.now();

    sessionExercises = widget.exercises.map((exercise) {
      final setCount = int.tryParse(exercise['sets'].toString()) ?? 1;

      final targetReps = int.tryParse(exercise['targetReps'].toString()) ?? 10;

      final sets = List.generate(
        setCount,
        (index) => {
          'set': index + 1,
          'weight': 0.0,
          'reps': targetReps,
          'completed': false,
        },
      );

      return {
        'id': exercise['id']?.toString() ?? '',
        'name': exercise['name']?.toString() ?? '',
        'englishName': exercise['englishName']?.toString() ?? '',
        'muscle': exercise['muscle']?.toString() ?? '',
        'targetReps': targetReps,
        'sets': sets,
      };
    }).toList();

    _loadAllPreviousPerformance();

    elapsedTimer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted || finished) return;

      setState(() {
        elapsedSeconds++;
      });
    });
  }

  Future<void> _loadAllPreviousPerformance() async {
    for (final exercise in sessionExercises) {
      final name = exercise['name']?.toString() ?? '';

      final sets = exercise['sets'];

      if (sets is! List) continue;

      for (final rawSet in sets) {
        if (rawSet is! Map) continue;

        final setNumber = _toInt(rawSet['set']);

        if (name.trim().isEmpty || setNumber <= 0) {
          continue;
        }

        final key = _previousKey(name, setNumber);

        try {
          final previous = await FitnessStorage.getLastSetPerformance(
            name,
            setNumber: setNumber,
          );

          previousPerformance[key] = previous;
        } catch (_) {
          previousPerformance[key] = null;
        }
      }
    }

    if (!mounted) return;

    setState(() {
      loadingPrevious = false;
    });
  }

  String _previousKey(String exerciseName, int setNumber) {
    return '${exerciseName.trim()}__$setNumber';
  }

  Map<String, dynamic>? _getPrevious(
    Map<String, dynamic> exercise,
    int setNumber,
  ) {
    final name = exercise['name']?.toString() ?? '';

    return previousPerformance[_previousKey(name, setNumber)];
  }

  @override
  void dispose() {
    elapsedTimer?.cancel();
    restTimer?.cancel();
    _disposeControllers();
    super.dispose();
  }

  void _disposeControllers() {
    for (final exercise in sessionExercises) {
      final sets = exercise['sets'];

      if (sets is! List) continue;

      for (final rawSet in sets) {
        if (rawSet is Map) {
          final weightController = rawSet['_weightController'];

          final repsController = rawSet['_repsController'];

          if (weightController is TextEditingController) {
            weightController.dispose();
          }

          if (repsController is TextEditingController) {
            repsController.dispose();
          }
        }
      }
    }
  }

  TextEditingController _weightController(Map<String, dynamic> set) {
    final existing = set['_weightController'];

    if (existing is TextEditingController) {
      return existing;
    }

    final controller = TextEditingController(
      text: _formatNumber(_toDouble(set['weight'])),
    );

    set['_weightController'] = controller;

    return controller;
  }

  TextEditingController _repsController(Map<String, dynamic> set) {
    final existing = set['_repsController'];

    if (existing is TextEditingController) {
      return existing;
    }

    final controller = TextEditingController(
      text: _toInt(set['reps']).toString(),
    );

    set['_repsController'] = controller;

    return controller;
  }

  double _toDouble(dynamic value) {
    if (value is double) return value;

    if (value is int) {
      return value.toDouble();
    }

    return double.tryParse(value?.toString() ?? '') ?? 0;
  }

  int _toInt(dynamic value) {
    if (value is int) return value;

    if (value is double) {
      return value.round();
    }

    return int.tryParse(value?.toString() ?? '') ?? 0;
  }

  String _formatNumber(double value) {
    if (value == 0) return '';

    if (value == value.roundToDouble()) {
      return value.toInt().toString();
    }

    return value.toString();
  }

  bool _allSetsCompleted() {
    for (final exercise in sessionExercises) {
      final sets = exercise['sets'];

      if (sets is! List) {
        return false;
      }

      for (final rawSet in sets) {
        if (rawSet['completed'] != true) {
          return false;
        }
      }
    }

    return true;
  }

  int _completedSetsCount() {
    var count = 0;

    for (final exercise in sessionExercises) {
      final sets = exercise['sets'];

      if (sets is! List) continue;

      for (final rawSet in sets) {
        if (rawSet['completed'] == true) {
          count++;
        }
      }
    }

    return count;
  }

  int _totalSetsCount() {
    var count = 0;

    for (final exercise in sessionExercises) {
      final sets = exercise['sets'];

      if (sets is List) {
        count += sets.length;
      }
    }

    return count;
  }

  // ==========================================================
  // ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¹ط·آ·ط¢آ¢ط·آ¢ط¢آ¾ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ­ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ¸ط·آ·ط¢آ£ط·آ¢ط¢آ¢ط·آ£ط¢آ¢ط£آ¢أ¢â€ڑآ¬ط¹â€کط·آ¢ط¢آ¬ط·آ·ط¢آ¢ط·آ¢ط¢آ¦ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ¸ط·آ·ط¢آ·ط·آ¢ط¢آ¸ط·آ·ط¢آ¢ط·آ¢ط¢آ¹ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ¸ط·آ·ط¢آ£ط·آ¢ط¢آ¢ط·آ£ط¢آ¢ط£آ¢أ¢â€ڑآ¬ط¹â€کط·آ¢ط¢آ¬ط·آ£ط¢آ¢ط£آ¢أ¢â‚¬ع‘ط¢آ¬ط·آ¹أ¢â‚¬آ  ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ§ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ¸ط·آ·ط¢آ£ط·آ¢ط¢آ¢ط·آ£ط¢آ¢ط£آ¢أ¢â€ڑآ¬ط¹â€کط·آ¢ط¢آ¬ط·آ£ط¢آ¢ط£آ¢أ¢â‚¬ع‘ط¢آ¬ط·آ¹أ¢â‚¬آ ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ£ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ¯ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ§ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¥ط£آ¢أ¢â€ڑآ¬أ¢â€‍آ¢ ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ§ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ¸ط·آ·ط¢آ£ط·آ¢ط¢آ¢ط·آ£ط¢آ¢ط£آ¢أ¢â€ڑآ¬ط¹â€کط·آ¢ط¢آ¬ط·آ£ط¢آ¢ط£آ¢أ¢â‚¬ع‘ط¢آ¬ط·آ¹أ¢â‚¬آ ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ³ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ§ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ¨ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ¸ط·آ·ط¢آ£ط·آ¢ط¢آ¢ط·آ£ط¢آ¢ط£آ¢أ¢â€ڑآ¬ط¹â€کط·آ¢ط¢آ¬ط·آ·ط¢آ¹ط£آ¢أ¢â€ڑآ¬ط¹آ©
