  Future<void> _loadPrevious(
    Map<String, dynamic> exercise,
    Map<String, dynamic> set,
  ) async {
    final name = exercise['name']?.toString() ?? '';

    final setNumber = _toInt(set['set']);

    if (name.trim().isEmpty || setNumber <= 0) {
      return;
    }

    final key = _previousKey(name, setNumber);

    Map<String, dynamic>? previous = previousPerformance[key];

    if (previous == null && !previousPerformance.containsKey(key)) {
      try {
        previous = await FitnessStorage.getLastSetPerformance(
          name,
          setNumber: setNumber,
        );

        previousPerformance[key] = previous;
      } catch (_) {
        previousPerformance[key] = null;
      }
    }

    if (!mounted) return;

    if (previous == null) {
      final messenger = ScaffoldMessenger.of(context);

      messenger.showSnackBar(
