  void _startRest() {
    restTimer?.cancel();

    setState(() {
      restSeconds = 90;
    });

    restTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }

      if (restSeconds <= 1) {
        timer.cancel();

        setState(() {
          restSeconds = 0;
        });

        return;
      }

      setState(() {
        restSeconds--;
      });
    });
  }

  void _skipRest() {
    restTimer?.cancel();

    setState(() {
      restSeconds = 0;
    });
  }

