  Future<void> _finishWorkout() async {
    if (saving) return;

    setState(() {
      saving = true;
      finished = true;
    });

    elapsedTimer?.cancel();
    restTimer?.cancel();

    final cleanExercises = sessionExercises.map((exercise) {
      final rawSets = exercise['sets'];

      final cleanSets = <Map<String, dynamic>>[];

      if (rawSets is List) {
        for (final rawSet in rawSets) {
          if (rawSet is! Map) continue;

          cleanSets.add({
            'set': _toInt(rawSet['set']),
            'weight': _toDouble(rawSet['weight']),
            'reps': _toInt(rawSet['reps']),
            'completed': rawSet['completed'] == true,
          });
        }
      }

      return {
        'exerciseId': exercise['id']?.toString() ?? '',
        'exercise': exercise['name']?.toString() ?? '',
        'sets': cleanSets,
      };
    }).toList();

    await FitnessStorage.saveWorkoutSession(
      planId: widget.planId,
      planName: widget.planName,
      startedAt: startedAt ?? DateTime.now(),
      durationSeconds: elapsedSeconds,
      exercises: cleanExercises,
    );

    if (!mounted) return;

    Navigator.pop(context, true);
  }

