  Widget _buildSetRow(Map<String, dynamic> exercise, Map<String, dynamic> set) {
    final completed = set['completed'] == true;

    final weightController = _weightController(set);

    final repsController = _repsController(set);

    final setNumber = _toInt(set['set']);

    final previous = _getPrevious(exercise, setNumber);

    final previousWeight = previous == null
        ? 0.0
        : _toDouble(previous['weight']);

    final previousReps = previous == null ? 0 : _toInt(previous['reps']);

    final hasPrevious =
        previous != null && (previousWeight > 0 || previousReps > 0);

    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.fromLTRB(10, 10, 10, 11),
      decoration: BoxDecoration(
        color: completed
            ? pharmacyGreen.withValues(alpha: 0.07)
            : Colors.white.withValues(alpha: 0.035),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: completed
              ? pharmacyGreen.withValues(alpha: 0.25)
              : Colors.white.withValues(alpha: 0.05),
        ),
      ),
      child: Column(
        children: [
          Row(
            children: [
              Container(
                width: 35,
                height: 35,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: completed
                      ? pharmacyGreen
                      : Colors.white.withValues(alpha: 0.06),
                  shape: BoxShape.circle,
                ),
                child: completed
                    ? const Icon(Icons.check, color: Colors.white, size: 19)
                    : Text(
                        '$setNumber',
                        style: const TextStyle(
                          color: Colors.white70,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
              ),
              const SizedBox(width: 9),
              Expanded(
                child: _numberField(
                  controller: weightController,
                  label: t('weight'),
                  suffix: 'ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ¸ط·آ·ط¢آ·ط·آ¢ط¢آ¦ط·آ£ط¢آ¢ط£آ¢أ¢â‚¬ع‘ط¢آ¬ط£آ¢أ¢â‚¬â€چط¢آ¢ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ·ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ¬ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ¸ط·آ·ط¢آ£ط·آ¢ط¢آ¢ط·آ£ط¢آ¢ط£آ¢أ¢â€ڑآ¬ط¹â€کط·آ¢ط¢آ¬ط·آ·ط¢آ¢ط·آ¢ط¢آ¦',
                  enabled: !completed,
